def apply_content_plan(items_list, monsters_list, biome_actions, items_by_id):
    """Merge plan content into base game_data structures. Idempotent by id."""
    existing_item_ids = {it["id"] for it in items_list}
    for it in PLAN_ITEMS:
        if it["id"] not in existing_item_ids:
            items_list.append(it)
            items_by_id[it["id"]] = it
            existing_item_ids.add(it["id"])

    existing_monster_ids = {m["id"] for m in monsters_list}
    for m in PLAN_MONSTERS:
        if m["id"] not in existing_monster_ids:
            monsters_list.append(m)

    # Merge plan biome actions into existing actions (preserve actions like loot_ruins)
    for biome_id, plan_acts in PLAN_BIOME_ACTIONS.items():
        existing_acts = biome_actions.get(biome_id, [])
        existing_ids = {a["id"] for a in existing_acts}
        for pa in plan_acts:
            if pa["id"] in existing_ids:
                # Replace the existing action with the plan version
                for i, ea in enumerate(existing_acts):
                    if ea["id"] == pa["id"]:
                        existing_acts[i] = pa
                        break
            else:
                existing_acts.append(pa)
        biome_actions[biome_id] = existing_acts
